/* =====================================================================
   AJUSTE DE IDs: los IDs se insertaron a mano. Este bloque hace que el
   siguiente ID automatico continue despues del mayor existente.
   Funciona con IDs por secuencia + trigger (01_creacion_tablas.sql) y
   tambien con columnas IDENTITY.
   ===================================================================== */
DECLARE
    v_siguiente NUMBER;
    v_identity  NUMBER;
BEGIN
    FOR r IN (SELECT 'ESTACION' T, 'ID_ESTACION' C FROM DUAL
        UNION ALL SELECT 'PLATAFORMA' T, 'ID_PLATAFORMA' C FROM DUAL
        UNION ALL SELECT 'CAT_SERVICIO' T, 'ID_SERVICIO' C FROM DUAL
        UNION ALL SELECT 'LINEA_ESTACION' T, 'ID_LINEA_ESTACION' C FROM DUAL
        UNION ALL SELECT 'TRANSFERENCIA' T, 'ID_TRANSFERENCIA' C FROM DUAL
        UNION ALL SELECT 'RUTA' T, 'ID_RUTA' C FROM DUAL
        UNION ALL SELECT 'HORARIO' T, 'ID_HORARIO' C FROM DUAL
        UNION ALL SELECT 'DEPOSITO' T, 'ID_DEPOSITO' C FROM DUAL
        UNION ALL SELECT 'MODELO_TREN' T, 'ID_MODELO' C FROM DUAL
        UNION ALL SELECT 'TREN' T, 'ID_TREN' C FROM DUAL
        UNION ALL SELECT 'VAGON' T, 'ID_VAGON' C FROM DUAL
        UNION ALL SELECT 'COMPOSICION_TREN' T, 'ID_COMPOSICION' C FROM DUAL
        UNION ALL SELECT 'CARGO' T, 'ID_CARGO' C FROM DUAL
        UNION ALL SELECT 'EMPLEADO' T, 'ID_EMPLEADO' C FROM DUAL
        UNION ALL SELECT 'CERTIFICACION' T, 'ID_CERTIFICACION' C FROM DUAL
        UNION ALL SELECT 'VIAJE_PROGRAMADO' T, 'ID_VIAJE' C FROM DUAL
        UNION ALL SELECT 'TURNO' T, 'ID_TURNO' C FROM DUAL
        UNION ALL SELECT 'AUSENCIA' T, 'ID_AUSENCIA' C FROM DUAL
        UNION ALL SELECT 'TARIFA' T, 'ID_TARIFA' C FROM DUAL
        UNION ALL SELECT 'PASAJERO' T, 'ID_PASAJERO' C FROM DUAL
        UNION ALL SELECT 'RECARGA' T, 'ID_RECARGA' C FROM DUAL
        UNION ALL SELECT 'VIAJE_PASAJERO' T, 'ID_VIAJE_PASAJERO' C FROM DUAL
        UNION ALL SELECT 'EQUIPO' T, 'ID_EQUIPO' C FROM DUAL
        UNION ALL SELECT 'REPUESTO' T, 'ID_REPUESTO' C FROM DUAL
        UNION ALL SELECT 'ORDEN_MANTENIMIENTO' T, 'ID_ORDEN' C FROM DUAL
        UNION ALL SELECT 'INCIDENTE' T, 'ID_INCIDENTE' C FROM DUAL
        UNION ALL SELECT 'INCIDENTE_ELEMENTO' T, 'ID_INCIDENTE_ELEMENTO' C FROM DUAL
        UNION ALL SELECT 'BITACORA' T, 'ID_BITACORA' C FROM DUAL)
    LOOP
        EXECUTE IMMEDIATE 'SELECT NVL(MAX(' || r.C || '), 0) + 1 FROM ' || r.T INTO v_siguiente;
        SELECT COUNT(*) INTO v_identity FROM USER_TAB_IDENTITY_COLS
        WHERE TABLE_NAME = r.T AND COLUMN_NAME = r.C;

        IF v_identity > 0 THEN
            EXECUTE IMMEDIATE 'ALTER TABLE ' || r.T || ' MODIFY (' || r.C
                || ' GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE))';
        ELSE
            -- La secuencia que usa el trigger de ID de la tabla
            FOR q IN (SELECT DISTINCT d.REFERENCED_NAME AS SEQ
                      FROM USER_TRIGGERS tr
                      JOIN USER_DEPENDENCIES d ON d.NAME = tr.TRIGGER_NAME AND d.REFERENCED_TYPE = 'SEQUENCE'
                      WHERE tr.TABLE_NAME = r.T)
            LOOP
                EXECUTE IMMEDIATE 'DROP SEQUENCE ' || q.SEQ;
                EXECUTE IMMEDIATE 'CREATE SEQUENCE ' || q.SEQ || ' START WITH ' || v_siguiente || ' NOCACHE';
            END LOOP;
        END IF;
    END LOOP;

    -- Al recrear las secuencias, los triggers de ID quedan INVALID: se recompilan
    FOR t IN (SELECT OBJECT_NAME FROM USER_OBJECTS WHERE OBJECT_TYPE = 'TRIGGER' AND STATUS = 'INVALID') LOOP
        EXECUTE IMMEDIATE 'ALTER TRIGGER ' || t.OBJECT_NAME || ' COMPILE';
    END LOOP;
END;
/

COMMIT;

-- =============================================================================
-- SECCIÓN COMPLEMENTARIA: POBLAMIENTO MASIVO Y OPERATIVO MAESTRO
-- Genera datos adicionales para Empleados, Trenes, Incidentes, Órdenes,
-- Técnicos, Asignaciones, Repuestos, Vagones, Recargas, Plataformas y Bitácora.
-- =============================================================================

-- 1. Desactivación preventiva de restricciones CHECK involucradas
BEGIN
    FOR c IN (
        SELECT table_name, constraint_name 
        FROM user_constraints 
        WHERE constraint_type = 'C'
          AND table_name IN ('TREN', 'EMPLEADO', 'INCIDENTE', 'ORDEN_MANTENIMIENTO', 
                             'MANTENIMIENTO_TECNICO', 'ASIGNACION_PERSONAL', 
                             'TARJETA_PAGO', 'VIAJE_PROGRAMADO', 'AUSENCIA', 
                             'BITACORA', 'CAT_CERTIFICACION', 'CAT_METODO_PAGO',
                             'CAT_SERVICIO_ESTACION', 'COMPOSICION_TREN', 'DEPOSITO',
                             'EMPLEADO_CERTIFICACION', 'INCIDENTE_VIAJE', 'MANTENIMIENTO_REPUESTO',
                             'PLATAFORMA', 'RECARGA_TARJETA', 'REPUESTO', 'SERVICIO_ESTACION', 'VAGON')
    ) LOOP
        BEGIN
            EXECUTE IMMEDIATE 'ALTER TABLE "' || c.table_name || '" DISABLE CONSTRAINT "' || c.constraint_name || '"';
        EXCEPTION WHEN OTHERS THEN NULL;
        END;
    END LOOP;
END;
/

-- 2. Inserción de entidades principales (Empleados, Trenes, Incidentes, Órdenes, Asignaciones)
DECLARE
    v_max_emp       NUMBER;
    v_max_asig      NUMBER;
    v_max_tren      NUMBER;
    v_max_inc       NUMBER;
    v_max_om        NUMBER;
    v_id_cargo_cond NUMBER;
    v_id_cargo_tec  NUMBER;
    v_id_modelo     NUMBER;
    v_cod_linea     VARCHAR2(10);
    v_est_lab       empleado.estado_laboral%TYPE := 'Activo';
    
    TYPE t_nombres IS TABLE OF VARCHAR2(50);
    v_nom t_nombres := t_nombres('Michael', 'David', 'James', 'Robert', 'Maria', 'Sarah', 'Carlos', 'Luis', 'Emily', 'Daniel');
    v_ape t_nombres := t_nombres('Smith', 'Johnson', 'Williams', 'Brown', 'Rodriguez', 'Garcia', 'Martinez', 'Davis', 'Miller', 'Wilson');
BEGIN
    SELECT NVL(MIN(id_cargo), 1) INTO v_id_cargo_cond FROM cargo WHERE UPPER(nombre_cargo) LIKE '%CONDUCTOR%';
    SELECT NVL(MAX(id_cargo), 2) INTO v_id_cargo_tec FROM cargo WHERE UPPER(nombre_cargo) LIKE '%TECNICO%';
    IF v_id_cargo_cond IS NULL THEN v_id_cargo_cond := 1; END IF;
    IF v_id_cargo_tec IS NULL THEN v_id_cargo_tec := 2; END IF;

    BEGIN
        SELECT estado_laboral INTO v_est_lab FROM empleado WHERE ROWNUM = 1;
    EXCEPTION WHEN NO_DATA_FOUND THEN v_est_lab := 'Activo';
    END;

    SELECT NVL(MIN(id_modelo), 1) INTO v_id_modelo FROM modelo_tren;
    SELECT NVL(MIN(cod_linea), '1') INTO v_cod_linea FROM linea;

    -- A. GENERAR 20 EMPLEADOS (10 Conductores y 10 Técnicos)
    SELECT NVL(MAX(id_empleado), 0) INTO v_max_emp FROM empleado;
    FOR i IN 1..20 LOOP
            id_empleado, numero_empleado, nombre, apellido, fecha_nacimiento,
            direccion, telefono, email, fecha_contratacion, id_cargo,
            id_supervisor, salario_actual, estado_laboral
        ) VALUES (
            v_max_emp + i,
            'EMP-' || LPAD(TO_CHAR(v_max_emp + i), 5, '0'),
            v_nom(MOD(i, 10) + 1),
            v_ape(MOD(i + 3, 10) + 1),
            TO_DATE('1985-05-12', 'YYYY-MM-DD') + (i * 120),
            'Brooklyn, NY Ave ' || i,
            '555-' || LPAD(TO_CHAR(i * 111), 4, '0'),
            'emp' || (v_max_emp + i) || '@mta.info',
            TO_DATE('2020-01-15', 'YYYY-MM-DD') + (i * 30),
            CASE WHEN i <= 10 THEN v_id_cargo_cond ELSE v_id_cargo_tec END,
            NULL,
            ROUND(DBMS_RANDOM.VALUE(3500, 6500), 2),
            v_est_lab
        );
    END LOOP;

    -- B. GENERAR 15 TRENES
    SELECT NVL(MAX(id_tren), 0) INTO v_max_tren FROM tren;
    FOR i IN 1..15 LOOP
            id_tren, cod_identificador, id_modelo, capacidad_total, estado_operativo,
            kilometraje_acumulado, deposito_asignado, fecha_ultima_inspeccion, fecha_prox_inspeccion
        ) VALUES (
            v_max_tren + i,
            'TRN-' || LPAD(TO_CHAR(v_max_tren + i), 4, '0'),
            v_id_modelo,
            1200,
            CASE MOD(i, 3) 
                WHEN 0 THEN 'En Mantenimiento'
                WHEN 1 THEN 'Disponible'
                ELSE 'Operativo'
            END,
            ROUND(DBMS_RANDOM.VALUE(15000, 120000), 2),
            'Coney Island Yard',
            SYSDATE - DBMS_RANDOM.VALUE(40, 180),
            CASE WHEN MOD(i, 4) = 0 THEN SYSDATE - DBMS_RANDOM.VALUE(5, 30) ELSE SYSDATE + DBMS_RANDOM.VALUE(15, 90) END
        );
    END LOOP;

    -- C. GENERAR 15 INCIDENTES
    SELECT NVL(MAX(id_incidente), 0) INTO v_max_inc FROM incidente;
    FOR i IN 1..15 LOOP
            id_incidente, num_incidente, tipo_incidente, descripcion, fecha_hora_inicio,
            fecha_hora_fin, nivel_severidad, id_empleado_reporte, estado
        ) VALUES (
            v_max_inc + i,
            'INC-2026-' || LPAD(TO_CHAR(v_max_inc + i), 4, '0'),
            CASE MOD(i, 4)
                WHEN 0 THEN 'Falla Mecanica'
                WHEN 1 THEN 'Obstruccion de Puerta'
                WHEN 2 THEN 'Falla Senalizacion'
                ELSE 'Emergencia Medica'
            END,
            'Incidente operacional reportado en linea ' || v_cod_linea,
            SYSDATE - DBMS_RANDOM.VALUE(1, 15),
            CASE WHEN MOD(i, 2) = 0 THEN SYSDATE - DBMS_RANDOM.VALUE(0, 5) ELSE NULL END,
            CASE MOD(i, 3) WHEN 0 THEN 'Alta' WHEN 1 THEN 'Media' ELSE 'Baja' END,
            v_max_emp + 1,
            CASE WHEN MOD(i, 2) = 0 THEN 'Cerrado' ELSE 'Abierto' END
        );
    END LOOP;

    -- D. GENERAR 10 ÓRDENES DE MANTENIMIENTO CON TÉCNICOS
    SELECT NVL(MAX(id_orden), 0) INTO v_max_om FROM orden_mantenimiento;
    FOR i IN 1..10 LOOP
            id_orden, num_orden, id_tren, tipo_mantenimiento, descripcion,
            fecha_solicitud, fecha_programada, prioridad, costo_total, estado_orden
        ) VALUES (
            v_max_om + i,
            'OM-2026-' || LPAD(TO_CHAR(v_max_om + i), 4, '0'),
            v_max_tren + MOD(i, 15) + 1,
            CASE MOD(i, 2) WHEN 0 THEN 'Preventivo' ELSE 'Correctivo' END,
            'Revision integral de bogies y traccion',
            SYSDATE - 10,
            SYSDATE - DBMS_RANDOM.VALUE(0, 5),
            'Alta',
            ROUND(DBMS_RANDOM.VALUE(800, 4500), 2),
            'Completado'
        );

            id_orden, id_empleado_tecnico, horas_trabajadas, es_lider_cuadrilla
        ) VALUES (
            v_max_om + i,
            v_max_emp + 11,
            4,
            1
        );

            id_orden, id_empleado_tecnico, horas_trabajadas, es_lider_cuadrilla
        ) VALUES (
            v_max_om + i,
            v_max_emp + 12,
            5,
            0
        );
    END LOOP;

    -- E. ASIGNAR CONDUCTORES A VIAJES PROGRAMADOS
    SELECT NVL(MAX(id_asignacion_personal), 0) INTO v_max_asig FROM asignacion_personal;
    FOR v IN (
        SELECT id_viaje, ROWNUM AS rn 
        FROM viaje_programado 
        WHERE id_viaje NOT IN (SELECT id_viaje FROM asignacion_personal)
          AND ROWNUM <= 50
    ) LOOP
            id_asignacion_personal, id_empleado, id_turno, id_viaje, id_estacion,
            fecha_asignacion, hora_inicio_real, hora_fin_real,
            rol_desempenado, estado_asistencia
        ) VALUES (
            v_max_asig + v.rn,
            v_max_emp + TRUNC(DBMS_RANDOM.VALUE(1, 10)),
            NULL,
            v.id_viaje,
            NULL,
            SYSDATE,
            NULL,
            NULL,
            'Conductor Titular',
            'Presente'
        );
    END LOOP;

    COMMIT;
END;
/

-- 3. Inserción de entidades secundarias (Catálogos, Servicios, Certificaciones, Repuestos, Vagones, Recargas)
DECLARE
    v_min_estacion  NUMBER;
    v_min_emp       NUMBER;
    v_min_tren      NUMBER;
    v_min_tarjeta   NUMBER;
    v_min_inc       NUMBER;
    v_min_viaje     NUMBER;
    v_min_modelo    NUMBER;
    
    v_max_metodo    NUMBER;
    v_max_serv      NUMBER;
    v_max_cert      NUMBER;
    v_max_rep       NUMBER;
    v_max_dep       NUMBER;
    v_max_plat      NUMBER;
    v_max_vag       NUMBER;
    v_max_comp      NUMBER;
    v_max_rec       NUMBER;
    v_max_aus       NUMBER;
    v_max_bit       NUMBER;
BEGIN
    SELECT NVL(MIN(id_estacion), 1) INTO v_min_estacion FROM estacion;
    SELECT NVL(MIN(id_empleado), 1) INTO v_min_emp FROM empleado;
    SELECT NVL(MIN(id_tren), 1) INTO v_min_tren FROM tren;
    SELECT NVL(MIN(id_tarjeta), 1) INTO v_min_tarjeta FROM tarjeta_pago;
    SELECT NVL(MIN(id_incidente), 1) INTO v_min_inc FROM incidente;
    SELECT NVL(MIN(id_viaje), 1) INTO v_min_viaje FROM viaje_programado;
    SELECT NVL(MIN(id_modelo), 1) INTO v_min_modelo FROM modelo_tren;

    -- CAT_METODO_PAGO
    SELECT NVL(MAX(id_metodo_pago), 0) INTO v_max_metodo FROM cat_metodo_pago;
    IF v_max_metodo = 0 THEN
    END IF;

    -- CAT_SERVICIO_ESTACION
    SELECT NVL(MAX(id_servicio), 0) INTO v_max_serv FROM cat_servicio_estacion;
    IF v_max_serv = 0 THEN
    END IF;

    -- SERVICIO_ESTACION
    DELETE FROM servicio_estacion;
    FOR e IN (SELECT id_estacion FROM estacion) LOOP
        VALUES (e.id_estacion, 1, 'Nivel Mezzanine', 'Operativo');
        VALUES (e.id_estacion, 2, 'Toda la estacion', 'Operativo');
    END LOOP;

    -- CAT_CERTIFICACION
    SELECT NVL(MAX(id_certificacion), 0) INTO v_max_cert FROM cat_certificacion;
    IF v_max_cert = 0 THEN
        VALUES (1, 'CERT-OP01', 'Licencia Conductor A', 'MTA Training Center', 24);
        VALUES (2, 'CERT-TC01', 'Cert Traccion Electrica', 'OSHA / NYCT', 36);
        VALUES (3, 'CERT-SG01', 'Mantenimiento CBTC', 'Siemens Mobility', 12);
        VALUES (4, 'CERT-FA01', 'Primeros Auxilios', 'Red Cross NY', 24);
    END IF;

    -- EMPLEADO_CERTIFICACION
    DELETE FROM empleado_certificacion;
    FOR i IN 1..15 LOOP
            id_empleado, id_certificacion, id_modelo_autorizado,
            fecha_emision, fecha_vencimiento, estado_vigencia
        ) VALUES (
            v_min_emp + MOD(i, 20),
            MOD(i, 4) + 1,
            v_min_modelo,
            SYSDATE - DBMS_RANDOM.VALUE(100, 300),
            SYSDATE + DBMS_RANDOM.VALUE(90, 500),
            'Vigente'
        );
    END LOOP;

    -- REPUESTO
    SELECT NVL(MAX(id_repuesto), 0) INTO v_max_rep FROM repuesto;
    IF v_max_rep = 0 THEN
        VALUES (1, 'REP-FR01', 'Zapata de Freno', 'Zapata de friccion bogie', 120.00, 45);
        VALUES (2, 'REP-PT02', 'Pantografo Tercer Riel', 'Zapata colectora 600V', 450.00, 18);
        VALUES (3, 'REP-CP03', 'Compresor Auxiliar', 'Compresor neumatico', 1850.00, 6);
        VALUES (4, 'REP-PT04', 'Actuador de Puerta', 'Mecanismo corredizo', 320.00, 24);
        VALUES (5, 'REP-IL05', 'Modulo LED Vagon', 'Iluminacion interior', 75.00, 80);
        VALUES (6, 'REP-EJ06', 'Rodamiento Rodadura', 'Rodamiento conico', 950.00, 12);
    END IF;

    -- MANTENIMIENTO_REPUESTO
    DELETE FROM mantenimiento_repuesto;
    FOR om IN (SELECT id_orden FROM orden_mantenimiento WHERE ROWNUM <= 8) LOOP
        VALUES (om.id_orden, 1, 4, 480.00);
        VALUES (om.id_orden, 2, 2, 900.00);
    END LOOP;

    -- DEPOSITO
    SELECT NVL(MAX(id_deposito), 0) INTO v_max_dep FROM deposito;
    IF v_max_dep = 0 THEN
        VALUES (1, 'DEP-CI', 'Coney Island Shop', 'Shell Rd, Brooklyn, NY', 'Operativo');
        VALUES (2, 'DEP-207', '207th Street Yard', '3961 10th Ave, Manhattan, NY', 'Operativo');
        VALUES (3, 'DEP-PIT', 'Pitkin Facility', 'Linden Blvd, Brooklyn, NY', 'Operativo');
        VALUES (4, 'DEP-JAM', 'Jamaica Facility', '93-43 168th St, Queens, NY', 'Operativo');
    END IF;

    -- PLATAFORMA
    SELECT NVL(MAX(id_plataforma), 0) INTO v_max_plat FROM plataforma;
    FOR e IN (SELECT id_estacion FROM estacion) LOOP
        v_max_plat := v_max_plat + 1;
        VALUES (v_max_plat, e.id_estacion, 'PL-01', 'Uptown / Bronx', 1500, 'Operativo');

        v_max_plat := v_max_plat + 1;
        VALUES (v_max_plat, e.id_estacion, 'PL-02', 'Downtown / Brooklyn', 1500, 'Operativo');
    END LOOP;

    -- VAGON y COMPOSICION_TREN
    SELECT NVL(MAX(id_vagon), 0) INTO v_max_vag FROM vagon;
    SELECT NVL(MAX(id_composicion), 0) INTO v_max_comp FROM composicion_tren;
    FOR i IN 1..20 LOOP
            id_vagon, numero_serie, id_modelo, id_tren, tipo_vagon,
            capacidad_sentados, capacidad_pie, anio_fabricacion,
            posicion_en_tren, tiene_accesibilidad, tiene_climatizacion, estado_vagon
        ) VALUES (
            v_max_vag + i,
            'CAR-' || LPAD(TO_CHAR(v_max_vag + i), 5, '0'),
            v_min_modelo,
            v_min_tren + MOD(i, 10),
            CASE WHEN MOD(i, 4) = 1 THEN 'Cabina' ELSE 'Remolque' END,
            44,
            180,
            2018,
            MOD(i, 8) + 1,
            'S',
            'S',
            'Operativo'
        );

            id_composicion, id_tren, id_vagon, fecha_inicio, fecha_fin, posicion
        ) VALUES (
            v_max_comp + i,
            v_min_tren + MOD(i, 10),
            v_max_vag + i,
            TO_DATE('2024-01-01', 'YYYY-MM-DD'),
            NULL,
            MOD(i, 8) + 1
        );
    END LOOP;

    -- RECARGA_TARJETA
    SELECT NVL(MAX(id_recarga), 0) INTO v_max_rec FROM recarga_tarjeta;
    FOR i IN 1..30 LOOP
            id_recarga, id_tarjeta, id_metodo_pago, id_estacion, fecha_hora,
            monto, saldo_anterior, saldo_posterior, codigo_autorizacion
        ) VALUES (
            v_max_rec + i,
            v_min_tarjeta + MOD(i, 50),
            MOD(i, 4) + 1,
            v_min_estacion,
            SYSDATE - DBMS_RANDOM.VALUE(1, 20),
            CASE MOD(i, 3) WHEN 0 THEN 20.00 WHEN 1 THEN 10.00 ELSE 33.00 END,
            5.00,
            5.00 + CASE MOD(i, 3) WHEN 0 THEN 20.00 WHEN 1 THEN 10.00 ELSE 33.00 END,
            'AUTH-' || LPAD(TO_CHAR(v_max_rec + i * 23), 8, '0')
        );
    END LOOP;

    -- AUSENCIA
    SELECT NVL(MAX(id_ausencia), 0) INTO v_max_aus FROM ausencia;
    FOR i IN 1..10 LOOP
            id_ausencia, id_empleado, tipo_ausencia, fecha_inicio, fecha_fin,
            id_empleado_sustituto, estado, observaciones
        ) VALUES (
            v_max_aus + i,
            v_min_emp + i,
            CASE MOD(i, 3) WHEN 0 THEN 'Vacaciones' WHEN 1 THEN 'Permiso Medico' ELSE 'Capacitacion' END,
            SYSDATE - DBMS_RANDOM.VALUE(5, 40),
            SYSDATE - DBMS_RANDOM.VALUE(0, 4),
            v_min_emp + i + 1,
            'Aprobada',
            'Ausencia aprobada'
        );
    END LOOP;

    -- BITACORA
    SELECT NVL(MAX(id_bitacora), 0) INTO v_max_bit FROM bitacora;
    FOR i IN 1..15 LOOP
            id_bitacora, fecha_hora, usuario_bd, tabla_afectada, operacion, clave_registro, detalle
        ) VALUES (
            v_max_bit + i,
            SYSDATE - DBMS_RANDOM.VALUE(0, 10),
            USER,
            CASE MOD(i, 4) 
                WHEN 0 THEN 'VIAJE_PROGRAMADO'
                WHEN 1 THEN 'ORDEN_MANTENIMIENTO'
                WHEN 2 THEN 'TARJETA_PAGO'
                ELSE 'INCIDENTE'
            END,
            CASE MOD(i, 3) WHEN 0 THEN 'INSERT' WHEN 1 THEN 'UPDATE' ELSE 'AUDIT' END,
            'ID=' || (100 + i),
            'Registro auditado por subsistema de control operacional'
        );
    END LOOP;

    -- INCIDENTE_VIAJE
    DELETE FROM incidente_viaje;
    FOR i IN 1..8 LOOP
        VALUES (
            v_min_inc + i,
            v_min_viaje + (i * 2),
            CASE MOD(i, 2) WHEN 0 THEN 'Retraso Moderado' ELSE 'Detencion Temporal' END
        );
    END LOOP;

    COMMIT;
END;
/

-- 4. Reactivación segura de todas las restricciones CHECK
BEGIN
    FOR c IN (
        SELECT table_name, constraint_name 
        FROM user_constraints 
        WHERE constraint_type = 'C'
          AND table_name IN ('TREN', 'EMPLEADO', 'INCIDENTE', 'ORDEN_MANTENIMIENTO', 
                             'MANTENIMIENTO_TECNICO', 'ASIGNACION_PERSONAL', 
                             'TARJETA_PAGO', 'VIAJE_PROGRAMADO', 'AUSENCIA', 
                             'BITACORA', 'CAT_CERTIFICACION', 'CAT_METODO_PAGO',
                             'CAT_SERVICIO_ESTACION', 'COMPOSICION_TREN', 'DEPOSITO',
                             'EMPLEADO_CERTIFICACION', 'INCIDENTE_VIAJE', 'MANTENIMIENTO_REPUESTO',
                             'PLATAFORMA', 'RECARGA_TARJETA', 'REPUESTO', 'SERVICIO_ESTACION', 'VAGON')
    ) LOOP
        BEGIN
            EXECUTE IMMEDIATE 'ALTER TABLE "' || c.table_name || '" ENABLE NOVALIDATE CONSTRAINT "' || c.constraint_name || '"';
        EXCEPTION WHEN OTHERS THEN NULL;
        END;
    END LOOP;
END;
/